CREATE TABLE roles (name VARCHAR(16) PRIMARY KEY);
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, enabled BOOLEAN NOT NULL, created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_name VARCHAR(16) NOT NULL, PRIMARY KEY(user_id,role_name),FOREIGN KEY (user_id) REFERENCES users(id),FOREIGN KEY (role_name) REFERENCES roles(name));
CREATE TABLE media (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(200) NOT NULL,storage_key VARCHAR(100) NOT NULL UNIQUE,content_type VARCHAR(100) NOT NULL,size BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL,uploaded_by BIGINT,FOREIGN KEY (uploaded_by) REFERENCES users(id));
CREATE TABLE companies (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE TABLE categories (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE TABLE projects (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL,company_id BIGINT,FOREIGN KEY (company_id) REFERENCES companies(id));
CREATE TABLE technologies (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE TABLE skills (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE TABLE experience (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL,company_id BIGINT,FOREIGN KEY (company_id) REFERENCES companies(id));
CREATE TABLE education (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE TABLE services (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE TABLE articles (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL,category_id BIGINT,author_id BIGINT,FOREIGN KEY (category_id) REFERENCES categories(id),FOREIGN KEY (author_id) REFERENCES users(id));
CREATE TABLE resumes (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL,media_id BIGINT,FOREIGN KEY (media_id) REFERENCES media(id));
CREATE TABLE timeline_events (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE TABLE profiles (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE TABLE settings (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,summary VARCHAR(3000) NOT NULL,category VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,featured BOOLEAN NOT NULL,sort_order INTEGER NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE INDEX idx_projects_published_order ON projects(published,sort_order);
CREATE INDEX idx_technologies_published_order ON technologies(published,sort_order);
CREATE INDEX idx_skills_published_order ON skills(published,sort_order);
CREATE INDEX idx_experience_published_order ON experience(published,sort_order);
CREATE INDEX idx_education_published_order ON education(published,sort_order);
CREATE INDEX idx_companies_published_order ON companies(published,sort_order);
CREATE INDEX idx_services_published_order ON services(published,sort_order);
CREATE INDEX idx_articles_published_order ON articles(published,sort_order);
CREATE INDEX idx_categories_published_order ON categories(published,sort_order);
CREATE INDEX idx_resumes_published_order ON resumes(published,sort_order);
CREATE INDEX idx_timeline_events_published_order ON timeline_events(published,sort_order);
CREATE INDEX idx_profiles_published_order ON profiles(published,sort_order);
CREATE INDEX idx_settings_published_order ON settings(published,sort_order);
CREATE TABLE project_technologies (id BIGINT AUTO_INCREMENT PRIMARY KEY,project_id BIGINT NOT NULL,technology_id BIGINT NOT NULL,UNIQUE(project_id,technology_id),FOREIGN KEY (project_id) REFERENCES projects(id),FOREIGN KEY (technology_id) REFERENCES technologies(id));
CREATE TABLE contact_messages (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(40),company VARCHAR(180),project_type VARCHAR(100),budget VARCHAR(100),message VARCHAR(5000) NOT NULL,status VARCHAR(24) NOT NULL,submission_key VARCHAR(80) UNIQUE,created_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE INDEX idx_contacts_status_created ON contact_messages(status,created_at);
CREATE TABLE analytics_events (id BIGINT AUTO_INCREMENT PRIMARY KEY,event_type VARCHAR(30) NOT NULL,resource VARCHAR(180),created_at TIMESTAMP(6) NOT NULL);
CREATE INDEX idx_events_type_created ON analytics_events(event_type,created_at);
